/**
 * 손그림 학교 아이콘(카테고리용) — 원본: "School Handmade" 아이콘 세트.
 * Designed by Freepik and distributed by Flaticon (무료 라이선스, 저작자 표시 필수 → 푸터에 표기).
 * 원본 SVG 의 path 만 뽑아 한 가지 색(currentColor)으로 칠한다 → 색은 text-* 토큰으로 바뀐다.
 * 이 파일은 스크립트로 만든 산출물이므로 path 를 손으로 고치지 않는다.
 *  - viewBox 는 그림 경계에 맞춘 정사각형 → 아이콘끼리 크기가 고르게 보인다.
 *  - 파생본(라이선스상 수정 허용): open-book-hangul(ABC→ㄱㄴㄷ), blackboard-uriban(SCHOOL→우리 반),
 *    math-123(숫자 1·2·3 조합), globe-flask(지구본+플라스크), palette-note-ball(팔레트+음표+축구공).
 */

export type HandmadeLayer = {
  /** 원본 좌표 → 아이콘 좌표 배치(조합 아이콘용). */
  transform?: string
  /** 채워 그리는 선화(원본 path). */
  paths: string[]
  /** 이 층에서 지워 낼 영역(아이콘 좌표) — 앞에 놓인 그림 뒤의 선을 가린다. */
  knockout?: string[]
}

export type HandmadeIconData = {
  viewBox: string
  /** 아래층부터 차례로 그린다. */
  layers: HandmadeLayer[]
  /** 선으로 긋는 손글씨 획(글자 윤곽·음영). width = viewBox 단위 굵기. */
  strokes?: { d: string; width: number }[]
}

